final notifications = FlutterLocalNotificationsPlugin();
String gid() => DateTime.now().microsecondsSinceEpoch.toString();
String jd(DateTime d){final j=Gregorian.fromDateTime(d).toJalali();return '${j.year}/${j.month.toString().padLeft(2,'0')}/${j.day.toString().padLeft(2,'0')}';}
String tm(DateTime d)=>'${d.hour.toString().padLeft(2,'0')}:${d.minute.toString().padLeft(2,'0')}';
bool sd(DateTime a,DateTime b)=>a.year==b.year&&a.month==b.month&&a.day==b.day;

Future<DateTime?> pickDT(BuildContext c,DateTime initial,{bool past=true})async{final now=Gregorian.fromDateTime(DateTime.now()).toJalali();final p=await showJalaliDatePicker(c,initialDate:Gregorian.fromDateTime(initial).toJalali(),firstDate:past?Jalali(1380,1,1):now,lastDate:Jalali(1450,12,29),textDirection:TextDirection.rtl);if(p==null)return null;final t=await showTimePicker(context:c,initialTime:TimeOfDay.fromDateTime(initial));if(t==null)return null;final g=p.toGregorian();return DateTime(g.year,g.month,g.day,t.hour,t.minute);}

class FU{String id,text;DateTime at;DateTime? rem;FU({required this.id,required this.text,required this.at,this.rem});Map<String,dynamic> j()=>{'id':id,'text':text,'at':at.toIso8601String(),'rem':rem?.toIso8601String()};factory FU.f(Map<String,dynamic>x)=>FU(id:'${x['id']??gid()}',text:'${x['text']??''}',at:DateTime.tryParse('${x['at']}')??DateTime.now(),rem:x['rem']==null?null:DateTime.tryParse('${x['rem']}'));}
class AI{String id,title,note,cat;DateTime date;DateTime? rem;bool task,arch,trash;List<String> tags,check;List<bool> done;List<FU> fs;AI({required this.id,required this.title,required this.note,required this.cat,required this.date,required this.task,required this.tags,required this.check,required this.done,required this.fs,this.rem,this.arch=false,this.trash=false});Map<String,dynamic>j()=>{'id':id,'title':title,'note':note,'cat':cat,'date':date.toIso8601String(),'rem':rem?.toIso8601String(),'task':task,'arch':arch,'trash':trash,'tags':tags,'check':check,'done':done,'fs':fs.map((e)=>e.j()).toList()};factory AI.f(Map<String,dynamic>x){final c=List<String>.from(x['check']??x['checklist']??[]);final d=List<bool>.from(x['done']??x['checked']??[]);while(d.length<c.length)d.add(false);return AI(id:'${x['id']??gid()}',title:'${x['title']??''}',note:'${x['note']??x['description']??''}',cat:'${x['cat']??x['category']??'عمومی'}',date:DateTime.tryParse('${x['date']}')??DateTime.now(),rem:x['rem']==null?null:DateTime.tryParse('${x['rem']}'),task:x['task']??false,arch:x['arch']??x['archived']??false,trash:x['trash']??x['trashed']??false,tags:List<String>.from(x['tags']??[]),check:c,done:d,fs:(x['fs']??x['followUps']??[]).map((e)=>FU.f(Map<String,dynamic>.from(e))).toList());}}

Future<void> initN()async{tz.initializeTimeZones();tz.setLocalLocation(tz.getLocation('Asia/Tehran'));await notifications.initialize(const InitializationSettings(android:AndroidInitializationSettings('@mipmap/ic_launcher')));}
Future<void> reminder(int id,String title,String body,DateTime when)async{if(!when.isAfter(DateTime.now()))return;const a=AndroidNotificationDetails('arvin','یادآوری آروین',channelDescription:'یادآوری',importance:Importance.max,priority:Priority.high);await notifications.zonedSchedule(id,title,body,tz.TZDateTime.from(when,tz.local),const NotificationDetails(android:a),androidScheduleMode:AndroidScheduleMode.inexactAllowWhileIdle);}
Future<void> main()async{WidgetsFlutterBinding.ensureInitialized();await initN();runApp(const App());}
class App extends StatefulWidget{const App({super.key});@override State<App>createState()=>SApp();}
class SApp extends State<App>{String font='Vazirmatn';bool dark=false;@override void initState(){super.initState();load();}Future<void>load()async{final p=await SharedPreferences.getInstance();if(!mounted)return;setState((){font=p.getString('font')??'Vazirmatn';dark=p.getBool('dark')??false;});}Future<void>sf(String v)async{final p=await SharedPreferences.getInstance();await p.setString('font',v);if(mounted)setState(()=>font=v);}Future<void>sdark(bool v)async{final p=await SharedPreferences.getInstance();await p.setBool('dark',v);if(mounted)setState(()=>dark=v);}@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'آروین',theme:ThemeData(useMaterial3:true,fontFamily:font),darkTheme:ThemeData(useMaterial3:true,fontFamily:font,brightness:Brightness.dark),themeMode:dark?ThemeMode.dark:ThemeMode.light,home:Directionality(textDirection:TextDirection.rtl,child:Home(font:font,dark:dark,onFont:sf,onDark:sdark)));}

class Home extends StatefulWidget{final String font;final bool dark;final Future<void>Function(String)onFont;final Future<void>Function(bool)onDark;const Home({super.key,required this.font,required this.dark,required this.onFont,required this.onDark});@override State<Home>createState()=>SH();}
class SH extends State<Home>{List<AI> all=[];List<String>cats=['عمومی'],tags=[];String cf='همه',sf='همه',sort='آخرین وارده';bool rev=false,loading=true,multi=false;final sel=<String>{};String sr='امروز',sl='سطل زباله';
@override void initState(){super.initState();load();}
Future<void>load()async{final p=await SharedPreferences.getInstance();final raw=p.getString('items');if(raw!=null)all=(jsonDecode(raw)as List).map((e)=>AI.f(Map<String,dynamic>.from(e))).toList();cats=p.getStringList('cats')??['عمومی'];tags=p.getStringList('tags')??[];cf=p.getString('cf')??'همه';sf=p.getString('sf')??'همه';sort=p.getString('sort')??'آخرین وارده';rev=p.getBool('rev')??false;sr=p.getString('sr')??'امروز';sl=p.getString('sl')??'سطل زباله';if(mounted)setState(()=>loading=false);}
Future<void>save()async{final p=await SharedPreferences.getInstance();await p.setString('items',jsonEncode(all.map((e)=>e.j()).toList()));await p.setStringList('cats',cats);await p.setStringList('tags',tags);await p.setString('cf',cf);await p.setString('sf',sf);await p.setString('sort',sort);await p.setBool('rev',rev);await p.setString('sr',sr);await p.setString('sl',sl);}
List<AI>get shown{final now=DateTime.now();var r=all.where((x)=>!x.trash).where((x){if(sf=='بایگانی')return x.arch;if(x.arch)return false;if(sf=='امروز')return sd(x.date,now);if(sf=='آینده')return x.date.isAfter(now);if(sf=='عقب‌افتاده')return x.date.isBefore(now)&&!sd(x.date,now);if(sf=='یادداشت‌ها')return !x.task;if(sf=='کارها')return x.task;return true;}).where((x)=>cf=='همه'||x.cat==cf).toList();r.sort((a,b){int c;if(sort=='عنوان')c=a.title.compareTo(b.title);else if(sort=='تاریخ')c=a.date.compareTo(b.date);else{final aa=a.fs.isEmpty?a.date:a.fs.last.at;final bb=b.fs.isEmpty?b.date:b.fs.last.at;c=aa.compareTo(bb);}return rev?c:-c;});return r;}
Future<void>edit([AI?old,bool task=false])async{final x=await showModalBottomSheet<AI>(context:context,isScrollControlled:true,builder:(_)=>EditAI(old:old,task:old?.task??task,cats:cats,tags:tags));if(x==null)return;if(old==null)all.add(x);else{final i=all.indexWhere((e)=>e.id==old.id);if(i>=0)all[i]=x;}await save();if(x.rem!=null)await reminder(('i'+x.id).hashCode,'یادآوری آروین: ${x.title}',x.note,x.rem!);if(mounted)setState((){});}
Future<void>follow(AI x,[FU?old])async{final f=await showDialog<FU>(context:context,builder:(_)=>EditFU(old:old));if(f==null)return;if(old==null)x.fs.add(f);else{x.fs[x.fs.indexOf(old)]=f;}await save();if(f.rem!=null)await reminder(('f'+f.id).hashCode,'یادآوری پیگیری: ${x.title}',f.text,f.rem!);if(mounted)setState((){});}
Future<void>pdf(AI x)async{final d=pw.Document();d.addPage(pw.MultiPage(build:(_)=>[pw.Text(x.title),pw.Text(x.note),pw.Text('دسته: ${x.cat}'),pw.Text('${jd(x.date)} ${tm(x.date)}'),...x.fs.map((f)=>pw.Text('${jd(f.at)} ${tm(f.at)} ${f.text}'))]));await Printing.sharePdf(bytes:await d.save(),filename:'arvin_${x.id}.pdf');}
Future<void>pdfList()async{final d=pw.Document();d.addPage(pw.MultiPage(build:(_)=>shown.map((x)=>pw.Text('${x.title} | ${x.cat} | ${jd(x.date)}')).toList()));await Printing.sharePdf(bytes:await d.save(),filename:'arvin_list.pdf');}
Future<void>backup()async{final dir=await getApplicationDocumentsDirectory();final f=File('${dir.path}/arvin_backup.json');await f.writeAsString(jsonEncode({'items':all.map((e)=>e.j()).toList(),'cats':cats,'tags':tags}));await Share.shareXFiles([XFile(f.path)],text:'پشتیبان آروین');}
Future<void>restore()async{final r=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['json'],withData:true);if(r==null||r.files.single.bytes==null)return;final m=jsonDecode(utf8.decode(r.files.single.bytes!))as Map<String,dynamic>;all=(m['items']as List).map((e)=>AI.f(Map<String,dynamic>.from(e))).toList();cats=List<String>.from(m['cats']??['عمومی']);tags=List<String>.from(m['tags']??[]);await save();if(mounted)setState((){});}
Future<void>lists(String title,List<String>src,void Function(List<String>)done)async{final v=await showDialog<List<String>>(context:context,builder:(_)=>Manage(title,src));if(v!=null){done(v);await save();if(mounted)setState((){});}}
Future<void>swipe(AI x,String a)async{if(a=='امروز')x.date=DateTime.now();else if(a=='بایگانی')x.arch=true;else if(a=='سطل زباله')x.trash=true;else if(a=='پیگیری'&&x.task)await follow(x);else if(a=='ویرایش')await edit(x);else if(a=='اشتراک‌گذاری')await pdf(x);await save();if(mounted)setState((){});}
