class Manage extends StatefulWidget{final String title;final List<String>src;const Manage(this.title,this.src,{super.key});@override State<Manage>createState()=>SM();}
class SM extends State<Manage>{late List<String>list;final c=TextEditingController();@override void initState(){super.initState();list=[...widget.src];}@override void dispose(){c.dispose();super.dispose();}@override Widget build(BuildContext x)=>AlertDialog(title:Text(widget.title),content:SizedBox(width:330,height:320,child:Column(children:[TextField(controller:c,decoration:InputDecoration(labelText:'جدید',suffixIcon:IconButton(icon:const Icon(Icons.add),onPressed:(){final v=c.text.trim();if(v.isNotEmpty&&!list.contains(v)){setState(()=>list.add(v));c.clear();}}))),Expanded(child:ListView(children:list.map((v)=>ListTile(title:Text(v),trailing:IconButton(icon:const Icon(Icons.delete),onPressed:()=>setState(()=>list.remove(v)))).toList()))])),actions:[TextButton(onPressed:()=>Navigator.pop(x),child:const Text('لغو')),FilledButton(onPressed:()=>Navigator.pop(x,list),child:const Text('ذخیره'))]);}

class SetPage extends StatelessWidget{final String font;final bool dark;final Future<void>Function(String)onFont;final Future<void>Function(bool)onDark;final String l,r;final Future<void>Function(String,String)sw;const SetPage({super.key,required this.font,required this.dark,required this.onFont,required this.onDark,required this.l,required this.r,required this.sw});Future<String?>pick(BuildContext c)=>showDialog<String>(context:c,builder:(_)=>SimpleDialog(title:const Text('عملیات'),children:['هیچ‌کاری','امروز','بایگانی','سطل زباله','پیگیری','ویرایش','اشتراک‌گذاری'].map((v)=>SimpleDialogOption(onPressed:()=>Navigator.pop(c,v),child:Text(v))).toList()));@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('تنظیمات')),body:ListView(padding:const EdgeInsets.all(16),children:[SwitchListTile(title:const Text('حالت تاریک'),value:dark,onChanged:onDark),DropdownButtonFormField<String>(initialValue:font,items:const[DropdownMenuItem(value:'Vazirmatn',child:Text('Vazirmatn')),DropdownMenuItem(value:'Mitra',child:Text('Mitra')),DropdownMenuItem(value:'Homa',child:Text('Homa')),DropdownMenuItem(value:'Koodak',child:Text('Koodak')),DropdownMenuItem(value:'IRANSans',child:Text('IRANSans')),DropdownMenuItem(value:'Faraz',child:Text('Faraz'))],onChanged:(v){if(v!=null)onFont(v);},decoration:const InputDecoration(labelText:'فونت')),ListTile(title:Text('کشیدن راست: $r'),onTap:()async{final v=await pick(c);if(v!=null)sw(l,v);}),ListTile(title:Text('کشیدن چپ: $l'),onTap:()async{final v=await pick(c);if(v!=null)sw(v,r);})]));}
